pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        vm.assume(_newOwner != address(0) && _newOwner != c.owner());
        address caller = address(this);
        vm.prank(caller);
        bool success = c.setOwner(_newOwner);
        assertTrue(success && c.owner() == _newOwner);
    }
}

